    void BuildVehicle()
    {
        if(vehicleRoot!=null){vehicleRoot.gameObject.SetActive(false);Destroy(vehicleRoot.gameObject);}vehicleRoot=null;if(VehicleData==null||VehicleData.region!=World.Region)return;
        vehicleRoot=new GameObject(VehicleData.camper?"八座粉色房车":"八座旅行汽车").transform;vehicleRoot.position=VehicleData.position;vehicleRoot.rotation=Quaternion.Euler(0,VehicleData.yaw,0);var a=vehicleRoot.gameObject.AddComponent<RoyalArt>();Color pink=new Color(.91f,.61f,.74f),cream=new Color(.97f,.92f,.81f),black=new Color(.13f,.16f,.2f),blue=new Color(.61f,.84f,.91f);float length=VehicleData.camper?10.4f:7.8f;
        a.Piece("汽车底座",new Vector3(0,.25f,0),new Vector3(3.4f,.5f,length),black);a.Piece("车内地板",new Vector3(0,.57f,0),new Vector3(3.25f,.15f,length-.15f),cream);
        a.Piece("汽车后门",new Vector3(0,VehicleData.camper?1.68f:1.55f,-length/2+.05f),new Vector3(3.4f,VehicleData.camper?2.7f:2,.12f),pink);a.Piece(VehicleData.camper&&VehicleData.curtains?"拉上的后窗帘":"后窗",new Vector3(0,2.05f,-length/2+.12f),new Vector3(2,.65f,.04f),VehicleData.camper&&VehicleData.curtains?cream:blue);a.Piece("后门把手",new Vector3(.8f,1.15f,-length/2-.05f),new Vector3(.3f,.07f,.07f),black);
        a.Piece("车内暖灯",new Vector3(0,VehicleData.camper?2.93f:2.48f,-1.3f),new Vector3(.6f,.05f,.4f),cream);var lamp=new GameObject("房车照明").AddComponent<Light>();lamp.transform.SetParent(vehicleRoot,false);lamp.transform.localPosition=new Vector3(0,VehicleData.camper?2.8f:2.3f,-1.3f);lamp.type=LightType.Point;lamp.color=cream;lamp.range=8;lamp.intensity=.7f;
        foreach(float x in new[]{-1.55f,1.55f})foreach(float z in new[]{-2.6f,2.6f}){var wheel=a.Piece("滚动汽车轮胎",new Vector3(x,.38f,z),new Vector3(.75f,.2f,.75f),black,PrimitiveType.Cylinder);wheel.localRotation=Quaternion.Euler(0,0,90);a.Piece("银色轮毂",new Vector3(x*1.055f,.38f,z),new Vector3(.4f,.06f,.4f),Color.gray,PrimitiveType.Cylinder).localRotation=wheel.localRotation;}
        foreach(float x in new[]{-1.68f,1.68f}){a.Piece("车身侧板",new Vector3(x,1.05f,0),new Vector3(.12f,1,length-.1f),pink);for(int j=0;j<4;j++){a.Piece("车窗边框",new Vector3(x,1.85f,2.4f-j*1.65f),new Vector3(.08f,1.05f,1.4f),blue);if(VehicleData.camper&&VehicleData.curtains)a.Piece("拉上的车内窗帘",new Vector3(x*.92f,1.85f,2.4f-j*1.65f),new Vector3(.06f,1.06f,1.42f),new Color(.94f,.79f,.87f));}}
        a.Piece("前挡风玻璃下沿",new Vector3(0,1.05f,3.85f),new Vector3(3.4f,.55f,.12f),pink);a.Piece("挡风玻璃框",new Vector3(0,2.35f,3.85f),new Vector3(3.4f,.12f,.12f),pink);foreach(float x in new[]{-1.65f,1.65f})a.Piece("前挡风柱",new Vector3(x,1.8f,3.85f),new Vector3(.12f,1.2f,.12f),pink);
        a.Piece("车顶",new Vector3(0,VehicleData.camper?3.05f:2.6f,0),new Vector3(3.5f,.14f,length),cream);a.Piece("仪表台",new Vector3(0,1.38f,3.1f),new Vector3(3,.18f,.6f),black);var wheelSteer=a.Piece("驾驶座方向盘",new Vector3(-.72f,1.55f,2.9f),new Vector3(.5f,.07f,.5f),black,PrimitiveType.Cylinder);wheelSteer.localRotation=Quaternion.Euler(60,0,0);a.Piece("发光仪表",new Vector3(-.7f,1.55f,3.15f),new Vector3(.48f,.14f,.06f),blue);
        for(int i=0;i<8;i++){float x=i%2==0?-.7f:.7f,z=2.4f-(i/2)*1.6f;var seat=new GameObject(i==0?"驾驶座":i==1?"副驾驶座":"后排座椅"+i).transform;seat.SetParent(vehicleRoot,false);seat.localPosition=new Vector3(x,.6f,z);var sa=seat.gameObject.AddComponent<RoyalArt>();sa.Piece("座椅坐垫",new Vector3(0,.15f,0),new Vector3(.68f,.24f,.7f),pink);sa.Piece("座椅靠背",new Vector3(0,.65f,-.3f),new Vector3(.68f,1.1f,.15f),pink);sa.Piece("靠背头枕",new Vector3(0,1.22f,-.3f),new Vector3(.5f,.25f,.16f),cream);}
        int cargo=0;foreach(int n in VehicleData.cargo)cargo+=n;for(int i=0;i<3+(cargo>0?2:0);i++){a.Piece("可存物的行李箱",new Vector3(-1.2f+(i%3)*1.2f,.9f,-length/2+.5f-(i/3)*.15f),new Vector3(.65f,.6f,.38f),Color.HSVToRGB(i*.16f,.35f,.8f));a.Piece("行李箱把手",new Vector3(-1.2f+(i%3)*1.2f,1.23f,-length/2+.5f-(i/3)*.15f),new Vector3(.3f,.07f,.1f),black);}
        if(VehicleData.camper){a.Piece("房车小床",new Vector3(-.85f,.78f,-3.7f),new Vector3(1.3f,.35f,2.4f),pink);a.Piece("小床枕头",new Vector3(-.85f,1.05f,-4.5f),new Vector3(1,.2f,.4f),cream);a.Piece("洗漱台",new Vector3(1.02f,1,-1.4f),new Vector3(.9f,1.1f,.8f),cream);a.Piece("洗手池",new Vector3(1.02f,1.65f,-1.4f),new Vector3(.65f,.2f,.6f),blue);a.Piece("水龙头",new Vector3(1.02f,1.82f,-1.7f),new Vector3(.08f,.35f,.08f),Color.gray);a.Piece("牙刷杯",new Vector3(1.35f,1.77f,-1.3f),new Vector3(.15f,.2f,.15f),pink,PrimitiveType.Cylinder);a.Piece("房车马桶",new Vector3(1.05f,.87f,-2.45f),new Vector3(.65f,.7f,.8f),cream,PrimitiveType.Cylinder);a.Piece("房车浴盆",new Vector3(.72f,.88f,-4),new Vector3(1.1f,.65f,1.8f),cream);a.Piece("浴盆水面",new Vector3(.72f,1.22f,-4),new Vector3(.9f,.025f,1.6f),blue);a.Piece("沐浴露",new Vector3(1.35f,1.45f,-4.6f),new Vector3(.17f,.4f,.17f),pink);a.Piece("洗发露",new Vector3(1.35f,1.45f,-4.3f),new Vector3(.17f,.4f,.17f),blue);a.Piece("洗浴遮挡帘",new Vector3(.7f,2.1f,-3.05f),new Vector3(1.3f,1.4f,.04f),pink);}
        for(int i=0;i<VehicleData.passengers.Count;i++){var art=RoyalArt.Girl(vehicleRoot,true,false);art.name="车内乘客 · "+VehicleData.passengers[i].name;art.transform.localPosition=new Vector3((i+1)%2==0?-.7f:.7f,.85f,2.4f-((i+1)/2)*1.6f);art.transform.localScale=Vector3.one*(VehicleData.passengers[i].child?.65f:.85f);PoseCarPassenger(art,i);foreach(var nav in FindObjectsByType<NpcNavigation>(FindObjectsInactive.Include))if(PartyPersonKey(nav.transform)==VehicleData.passengers[i].key)nav.gameObject.SetActive(false);}
        foreach(var t in vehicleRoot.GetComponentsInChildren<Transform>())t.gameObject.layer=2;
        MakeVehicleCollision();
    }
    void PoseCarPassenger(RoyalArt art,int index)
    {
        var p=art.transform.localPosition;p.y=.25f;art.transform.localPosition=p;
        foreach(Transform part in art.transform){if(part.name=="小腿"){part.localPosition=new Vector3(part.localPosition.x,.49f,.28f);part.localRotation=Quaternion.Euler(35,0,0);}if(part.name=="鞋")part.localPosition=new Vector3(part.localPosition.x,.38f,.45f);if(part.name=="上衣"||part.name=="裙摆"||part.name=="鞋")part.GetComponent<Renderer>().sharedMaterial.color=Color.HSVToRGB(index*.14f,.32f,.87f);}
    }
    public bool TransferCarCargo(int id,int count,bool intoCar)
    {
        if(VehicleData==null||!CarRiding||id<1||id>=91&&id!=94||count<1||count>9999)return false;int[] source=intoCar?Inventory:VehicleData.cargo,destination=intoCar?VehicleData.cargo:Inventory;if(source[id]<count||destination[id]>9999-count)return false;source[id]-=count;destination[id]+=count;
        try{WorldSave.Write(WorldSave.Capture(World,Player,Inventory,Selected),WorldSave.PathName);}catch(System.Exception){source[id]+=count;destination[id]-=count;Notice="行李没能保存，物品已还原。";return false;}BuildVehicle();return true;
    }
    public void CloseCarCargo(){carCargoOpen=false;SetPaused(false);}
    void DrawCarCargo(float w,float h){float x=w/2-380,y=h/2-255;Panel(new Rect(x,y,760,510),Paper);Label(new Rect(x+20,y+10,600,38),"汽车行李箱 · 物品和数量会保存",24,Ink);if(GUI.Button(new Rect(x+630,y+10,110,35),"关闭 / Esc")){CloseCarCargo();return;}for(int n=0;n<12;n++){int index=cargoPage*12+n;if(index>=Blocks.BagItems.Length)break;int id=Blocks.BagItems[index];float row=y+60+n*33;Label(new Rect(x+20,row,360,30),Blocks.Names[id]+"  背包"+Inventory[id]+" / 行李"+VehicleData.cargo[id],16,Ink);if(GUI.Button(new Rect(x+390,row,160,29),"存入1个"))TransferCarCargo(id,1,true);if(GUI.Button(new Rect(x+570,row,160,29),"取出1个"))TransferCarCargo(id,1,false);}if(GUI.Button(new Rect(x+20,y+466,140,30),"上一页"))cargoPage=(cargoPage+7)%8;if(GUI.Button(new Rect(x+580,y+466,150,30),"下一页"))cargoPage=(cargoPage+1)%8;}
    void DrawVehicleHud(float w,float h){if(!CarRiding)return;float x=w-325,y=140;Panel(new Rect(x,y,303,VehicleData.camper?340:165),new Color(.12f,.17f,.23f,.95f));Label(new Rect(x+12,y+10,280,50),"八座汽车 · 乘客"+CarPassengerCount+"/7\n7房车 · O上客 · 数字0飞行",18,Color.white);if(GUI.Button(new Rect(x+12,y+68,130,34),"下车")){ExitCar();return;}if(GUI.Button(new Rect(x+150,y+68,140,34),"乘客下车"))LetPassengersOut();if(GUI.Button(new Rect(x+12,y+112,278,34),"打开行李箱")){carCargoOpen=true;inventoryOpen=false;SetPaused(true);}if(!VehicleData.camper)return;Label(new Rect(x+12,y+157,280,34),carCare==""?"H开关窗帘 · 停车后使用":carCare+"剩余"+Mathf.CeilToInt(carCareTime)+"秒",17,Color.white);string[] kinds={"睡觉","洗漱","马桶","洗澡"};for(int i=0;i<4;i++)if(GUI.Button(new Rect(x+12+(i%2)*140,y+203+(i/2)*43,130,36),kinds[i]))BeginCarCare(kinds[i]);}
